type LoadState =
  | { phase: "loading" }
  | { phase: "ready"; pricing: PublicPricing }
  | { phase: "failed" }
  | { phase: "misconfigured" };

type Viewer = { kind: "unknown" } | { kind: "guest" } | { kind: "member"; activeTier: string };

