// PROPERTY CONTROLS, PRD F14
// ============================================================================

addPropertyControls(BookmarksTray, mfControls({
  mfSeal: { type: ControlType.String, title: "Seal", hidden: () => true },
  drawerSide: {
    type: ControlType.Enum,
    title: "Drawer Side",
    options: ["right", "left"],
    optionTitles: ["Right Slide-Out", "Left Slide-Out"],
    defaultValue: CONFIG.drawerSide,
  },
  drawerWidth: {
    type: ControlType.Number,
    title: "Drawer Width",
    min: 280,
    max: 640,
    step: 10,
    unit: "px",
    defaultValue: 400,
  },
  backdrop: {
    type: ControlType.Enum,
    title: "Backdrop",
    options: ["dim", "blur", "none"],
    optionTitles: ["Dim", "Blur", "None"],
    displaySegmentedControl: true,
    defaultValue: "dim",
  },
  emptyStateText: {
    type: ControlType.String,
    title: "Empty Message",
    defaultValue: CONFIG.emptyStateText,
  },
  maxItems: {
    type: ControlType.Number,
    title: "Max Visible",
    min: 10,
    max: 200,
    step: 1,
    defaultValue: CONFIG.maxItems,
  },
  showBadge: {
    type: ControlType.Boolean,
    title: "Count Badge",
    defaultValue: CONFIG.showBadge,
  },
  badgeColor: {
    type: ControlType.Color,
    title: "Badge Color",
    optional: true,
    hidden: (props) => props.showBadge === false,
  },
  showSearch: {
    type: ControlType.Boolean,
    title: "Search",
    defaultValue: true,
  },
  showDates: {
    type: ControlType.Boolean,
    title: "Saved Date",
    defaultValue: true,
  },
  buttonStyle: {
    type: ControlType.Enum,
    title: "Button Style",
    options: ["outline", "soft", "ghost"],
    optionTitles: ["Outline", "Soft", "Icon Only"],
    defaultValue: "outline",
  },
  iconShape: {
    type: ControlType.Enum,
    title: "Icon",
    options: ["bookmark", "heart", "star"],
    optionTitles: ["Bookmark Ribbon", "Heart", "Star"],
    defaultValue: "bookmark",
  },
  iconSize: {
    type: ControlType.Number,
    title: "Icon Size",
    min: 12,
    max: 48,
    step: 1,
    unit: "px",
    defaultValue: 18,
  },
  showLabel: {
    type: ControlType.Boolean,
    title: "Show Label",
    defaultValue: false,
  },
  triggerLabel: {
    type: ControlType.String,
    title: "Button Label",
    defaultValue: "Saved",
    hidden: (props) => !props.showLabel,
  },
  loginPath: {
    type: ControlType.String,
    title: "Sign In Page",
    defaultValue: CONFIG.loginPath,
  },
  canvasPreview: {
    type: ControlType.Enum,
    title: "Canvas Preview",
    options: ["closed", "open"],
    optionTitles: ["Closed", "Open"],
    displaySegmentedControl: true,
    defaultValue: "closed",
  },
  accentColor: {
    type: ControlType.Color,
    title: "Accent Color",
    defaultValue: CONFIG.accentColor,
  },
  borderRadius: {
    type: ControlType.Number,
    title: "Corner Radius",
    min: 0,
    max: 32,
    step: 1,
    unit: "px",
    defaultValue: CONFIG.borderRadius,
  },
  ...mfAppearanceControls({ padding: 20, gap: 12, shadow: true }),
  labels: mfLabelControls(TRAY_LABELS),
}));
